import{_ as o,o as r,c as l,a2 as n}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"间章历史","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/间章历史.md","filePath":"中层/历史/间章历史.md","lastUpdated":1787065118000}'),s={name:"中层/历史/间章历史.md"};function i(a,t,g,e,u,p){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="间章历史" tabindex="-1">间章历史 <a class="header-anchor" href="#间章历史" aria-label="Permalink to &quot;间章历史&quot;">​</a></h1><p>间章为前传故事结束之后，到正传背景出现之前的时间段，包含了神机登神、布局新世界的关键过程。</p><p><strong>核心事件</strong>：</p><ol><li><p><strong>神机登神</strong>：神机在前传与维斯塔共同经历冒险后，开始暗中研究神权，最终成功掌握了<strong>上位创造神权</strong>，但她将其伪装成下位神权的样子。初代创造神作为&quot;无意识的弦&quot;被神机捕获、融入世界树；神机夺取其<strong>上位创造神权</strong>，下位创造神权仍由初代创造神充当载体、随其分装稀释给全体精灵。神机通过不断追本溯源、学习进化，主动掌握了上位创造神权。</p></li><li><p><strong>神机短暂黑化与回归</strong>：</p><ul><li><strong>黑化阶段</strong>：在刚成神时，神机曾有过一段差点&quot;黑化&quot;的历史，但她被维斯塔成功拉回，且没有因此放弃力量，反而更加谨慎地控制力量。</li><li><strong>回归机制</strong>：她的回归是&quot;半推半就&quot;的——她意识到这是自己故事线的一部分，是她人物弧光的完善过程。她顺势而为，完成了属于自己的故事逻辑。</li><li><strong>维斯塔的作用</strong>：维斯塔在尝试唤醒神机时，并不知道神机已经意识到这一切。维斯塔的纠结、担心失败的情绪，反而成了让叙事更真实的一环，最终促成了回归。</li></ul></li><li><p><strong>神机开始布局毁灭神的出现</strong>：</p><ul><li><strong>制造新物种</strong>：设计并创造了五大主族（牛、鹿、鹤、熊、甲）以及其他种族（狐族、狼族等），优化各个种族的特质。其直接动机为使毁灭神的出现可控——地球上必须存在一定数量的智慧生命作为<strong>毁灭神载体</strong>（类比人类作为初代变化神的载体）。五大主族的特质优化（牛=力量与坚韧 / 鹿=智慧与魔法适应性 / 鹤=政治与组织能力 / 熊=军事与战斗能力 / 甲=防御与工业能力）为神机设计时的<strong>生理特质</strong>；共同体时期的任务分工则是维斯塔基于这些特质<strong>人工规定的分工</strong>。</li><li><strong>设计狼族的基因锁</strong>：狼族的&quot;天真纯善&quot;特质是一个<strong>基因锁</strong>，真实特质是<strong>极端团结</strong>，成员之间不需要博弈、欺骗。这个锁让狼族认为所有人都是同伴，压制了他们的凶残本性。</li><li><strong>开始太空清除计划</strong>：为了防止毁灭神在其他星系出现，神机与维斯塔做出了清除所有地外智慧物种的决定。创造太空武器，与太空文明交战，大部分直接灭绝，只留数据存档。</li><li><strong>建造监控设施</strong>：建造世界树（喜马拉雅山附近的超大计算机中枢、信息收集中枢）、银河之眼（银河中心超大黑洞处的超级机器）等设施，用于监控和控制整个银河系。</li></ul></li><li><p><strong>福瑞的来历</strong>：神机创造了所有福瑞种族，作为&quot;更好的人类&quot;——那些&quot;只有人的优点、没有人的缺点&quot;的新物种。她更喜欢这些新物种，因为它们是一种&quot;更好的人类&quot;，同时它们也更像超算自己，是&quot;针对文明而优化的造物&quot;。</p></li><li><p><strong>叙事博弈的深化</strong>：神机开始对整个世界进行<strong>叙事建模</strong>，对时间线、故事线进行运算模拟，试图掌控故事走向，与叙事本身进行博弈。</p></li></ol><p><strong>关键补充</strong>：</p><ul><li><strong>不进入叙事的原因</strong>：正传中神机几乎不露面，这是刻意的。因为她知道一旦进入叙事，就不可避免地被叙事影响，而被叙事影响的人对叙事进行反干涉则需要付出更多的努力。</li><li><strong>预测精度</strong>：在创造神权支持下，她对世界的预估可以做到几十年、几百年甚至更长时间内<strong>百分百准确</strong>，精确到分子级甚至更高。但若不用创造神权，她无法对任何涉及基底层的事情做出准确预测——基底层对她而言完全&quot;随机&quot;；这种&quot;随机&quot;并非缺陷，而是她主动向作者让渡权力、避免作者毫无操作空间从而强行&quot;机械降灾&quot;的策略。</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../世界/神机谋划">神机谋划</a></li><li><a href="./../世界/地脉与魔法">地脉与魔法</a></li><li><a href="./../世界/历代三神">历代三神</a></li><li><a href="./../人物/神机">神机</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li><li><a href="./前传超算纪元">前传超算纪元</a></li><li><a href="./前传历史">前传历史</a></li><li><a href="./正传历史">正传历史</a></li></ul>',9)])])}const h=o(s,[["render",i]]);export{_ as __pageData,h as default};
